import{_ as o,C as d,o as n,c as s,j as e,a as r,E as i,a3 as c}from"./chunks/framework.DEy3KOfk.js";const b=JSON.parse('{"title":"Waypoints","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/waypoints/README.md"},"headers":[],"relativePath":"packages/waypoints/README.md","filePath":"packages/waypoints/README.md","lastUpdated":1791428389000}'),p={name:"packages/waypoints/README.md"},l={id:"waypoints",tabindex:"-1",class:"component-page-title"},m={class:"component-page-title__version"};function h(y,t,u,w,g,v){const a=d("Badge");return n(),s("div",null,[e("h1",l,[t[0]||(t[0]=e("span",{class:"component-page-title__text"},[r("Waypoints "),e("a",{class:"header-anchor",href:"#waypoints","aria-label":'Permalink to "Waypoints"'},"​")],-1)),e("span",m,[i(a,{type:"info",text:"v0.0.0"})])]),t[1]||(t[1]=c('<p>Server waypoints with vanilla commands and Java Locator Bar</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/packages/waypoints/docs/" target="_blank" rel="noreferrer">plugin guide</a> and <a href="https://filiphsps.github.io/pumpkin-plugins/api/plugins/waypoints/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Put <code>waypoints.wasm</code> from the plugin&#39;s GitHub release in your server&#39;s <code>plugins/</code> folder and restart. Hot reload cannot ask for permissions, so the first load needs a restart.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Pumpkin asks for these on the server console the first time the plugin loads.</p><table tabindex="0"><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td><code>fs.read.data</code></td><td>Read the waypoint store from the plugin data folder.</td></tr><tr><td><code>fs.write.data</code></td><td>Persist waypoint changes in the plugin data folder.</td></tr><tr><td><code>http.outbound</code></td><td>Check Pumpkin Market for plugin updates.</td></tr></tbody></table><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Permission</th><th>Default access</th></tr></thead><tbody><tr><td><code>/wp mark &lt;name&gt;</code></td><td>Save your current block position as a private waypoint</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp add &lt;name&gt; &lt;x&gt; &lt;y&gt; &lt;z&gt;</code></td><td>Save block coordinates as a private waypoint</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp list</code></td><td>List waypoints you can access; use all to include other dimensions</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp list &lt;scope&gt;</code></td><td>List waypoints you can access; use all to include other dimensions</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp show &lt;id&gt;</code></td><td>Show an accessible waypoint by UUID</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp access public &lt;id&gt;</code></td><td>Make a waypoint visible to everyone</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp access private &lt;id&gt;</code></td><td>Make a waypoint visible only to its owner</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp access allowlist &lt;id&gt;</code></td><td>Limit a waypoint to its owner and invited players</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp access invite &lt;id&gt; &lt;player&gt;</code></td><td>Invite an online player to an allowlisted waypoint</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp access revoke &lt;id&gt; &lt;player&gt;</code></td><td>Remove an online player from a waypoint allowlist</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp locator on &lt;id&gt;</code></td><td>Enable locator output for a waypoint</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp locator off &lt;id&gt;</code></td><td>Disable locator output for a waypoint</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp locator color &lt;id&gt; &lt;hex&gt;</code></td><td>Set or reset a waypoint RGB color</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp locator java-style &lt;id&gt; &lt;style&gt;</code></td><td>Set or reset a Java waypoint style resource ID</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp remove &lt;id&gt;</code></td><td>Remove a waypoint you own</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp send &lt;id&gt; &lt;adapter&gt;</code></td><td>Show a waypoint to yourself through a map adapter</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp send-to &lt;id&gt; &lt;player&gt; &lt;adapter&gt;</code></td><td>Send an accessible waypoint to an online player</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp admin list</code></td><td>List every saved waypoint</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp admin remove &lt;id&gt;</code></td><td>Remove any waypoint by UUID</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>This plugin has no configuration file.</p><h2 id="waypoints-and-access" tabindex="-1">Waypoints and access <a class="header-anchor" href="#waypoints-and-access" aria-label="Permalink to &quot;Waypoints and access&quot;">​</a></h2><p><code>/wp mark &quot;Home Base&quot;</code> saves your current block as a private waypoint. <code>/wp add &quot;Home Base&quot; 120 64 -30</code> saves explicit block coordinates. Use <code>/wp list</code> for this dimension or <code>/wp list all</code> across dimensions; the output includes each waypoint UUID for later commands.</p><p>Waypoints are private by default. Owners can make them public with <code>/wp access public &lt;id&gt;</code>, or use allowlist access with <code>/wp access allowlist &lt;id&gt;</code> and invite online players with <code>/wp access invite &lt;id&gt; &lt;player&gt;</code>. Owners can change or remove their own waypoints; operators can administer all records. Access lists store player UUIDs, not names.</p><p>The versioned store is <code>plugins/data/Waypoints/waypoints.json</code>. If it is malformed or has an unsupported schema, the plugin preserves it and refuses writes until the issue is corrected.</p><h2 id="java-locator-bar" tabindex="-1">Java Locator Bar <a class="header-anchor" href="#java-locator-bar" aria-label="Permalink to &quot;Java Locator Bar&quot;">​</a></h2><p>Locator output is off for new waypoints. Owners can enable it with <code>/wp locator on &lt;id&gt;</code>, set an RGB tint with <code>/wp locator color &lt;id&gt; #RRGGBB</code>, and optionally set a Java style resource ID with <code>/wp locator java-style &lt;id&gt; &lt;namespace:path&gt;</code>. Use <code>reset</code> to clear a color or style. Markers are sent only to Java players who can access the waypoint and are in its dimension. Disabling or removing a waypoint, changing dimensions, or revoking access removes its marker.</p><p>Custom styles need a compatible Java resource pack containing the matching <code>waypoint_style</code> assets. The Locator Bar can also be hidden by client settings or server rules. See the <a href="https://feedback.minecraft.net/hc/en-us/articles/37432144057997-Minecraft-Java-Edition-1-21-6-Chase-the-Skies" target="_blank" rel="noreferrer">Minecraft Java 1.21.6 release notes</a> for waypoint styles and colors.</p><p>The Pumpkin integration server is pinned to release <code>0.2.0+26.3-26.51</code>. Vanilla Java client behavior, including custom resource-pack styles, has not been manually verified for this implementation.</p><h2 id="map-adapters-and-bedrock" tabindex="-1">Map adapters and Bedrock <a class="header-anchor" href="#map-adapters-and-bedrock" aria-label="Permalink to &quot;Map adapters and Bedrock&quot;">​</a></h2><p>The <code>xaero-share</code> map adapter is registered but reports unavailable. Its share text and server-sent import behavior have not been verified with a current Xaero Minimap and World Map client, so <code>/wp send</code> and <code>/wp send-to</code> provide readable waypoint coordinates without claiming Xaero import or automatic synchronization. No Xaero version is claimed as tested.</p><p>Bedrock Locator Bar output is unsupported by the pinned Pumpkin API, which exposes no Bedrock waypoint packet or Locator Bar scripting interface. Waypoint commands and access rules remain available independently of locator output.</p>',22))])}const k=o(p,[["render",h]]);export{b as __pageData,k as default};
